import React, { useState } from 'react';
import Login from './screens/Login';
import Dashboard from './screens/Dashboard';
import Transactions from './screens/Transactions';
import Stock from './screens/Stock';
import Reports from './screens/Reports';
import NewPurchase from './screens/NewPurchase';
import NewSale from './screens/NewSale';
import Payment from './screens/Payment';
import Expenses from './screens/Expenses';
import './styles/theme.css';

export default function App() {
  const [activeScreen, setActiveScreen] = useState('login');

  // Helper to render bottom navigation bar on main app screens
  const renderBottomNav = () => {
    if (activeScreen === 'login') return null;

    return (
      <div style={bottomNavStyle}>
        <div onClick={() => setActiveScreen('dashboard')} style={{...navItemStyle, color: activeScreen === 'dashboard' ? '#1B4D3E' : '#666'}}>
          <span>📊</span>
          <span style={{fontSize: '11px', fontWeight: activeScreen === 'dashboard' ? 'bold' : 'normal'}}>Dashboard</span>
        </div>
        <div onClick={() => setActiveScreen('transactions')} style={{...navItemStyle, color: activeScreen === 'transactions' ? '#1B4D3E' : '#666'}}>
          <span>📑</span>
          <span style={{fontSize: '11px', fontWeight: activeScreen === 'transactions' ? 'bold' : 'normal'}}>Transactions</span>
        </div>
        <div onClick={() => setActiveScreen('stock')} style={{...navItemStyle, color: activeScreen === 'stock' ? '#1B4D3E' : '#666'}}>
          <span>📦</span>
          <span style={{fontSize: '11px', fontWeight: activeScreen === 'stock' ? 'bold' : 'normal'}}>Stock</span>
        </div>
        <div onClick={() => setActiveScreen('reports')} style={{...navItemStyle, color: activeScreen === 'reports' ? '#1B4D3E' : '#666'}}>
          <span>📈</span>
          <span style={{fontSize: '11px', fontWeight: activeScreen === 'reports' ? 'bold' : 'normal'}}>Reports</span>
        </div>
        <div onClick={() => setActiveScreen('expenses')} style={{...navItemStyle, color: activeScreen === 'expenses' ? '#1B4D3E' : '#666'}}>
          <span>⚙️</span>
          <span style={{fontSize: '11px', fontWeight: activeScreen === 'expenses' ? 'bold' : 'normal'}}>More</span>
        </div>

        {/* Floating Action Button */}
        <div 
          onClick={() => setActiveScreen('newPurchase')} 
          style={fabStyle}
          title="New Entry"
        >
          +
        </div>
      </div>
    );
  };

  return (
    <div style={{ background: '#FBF9F1', minHeight: '100vh', paddingBottom: '80px', position: 'relative' }}>
      {activeScreen === 'login' && <Login onLoginSuccess={() => setActiveScreen('dashboard')} />}
      {activeScreen === 'dashboard' && <Dashboard onNavigate={(screen) => setActiveScreen(screen)} />}
      {activeScreen === 'transactions' && <Transactions />}
      {activeScreen === 'stock' && <Stock />}
      {activeScreen === 'reports' && <Reports />}
      {activeScreen === 'newPurchase' && <NewPurchase />}
      {activeScreen === 'newSale' && <NewSale />}
      {activeScreen === 'payments' && <Payment />}
      {activeScreen === 'expenses' && <Expenses />}

      {renderBottomNav()}
    </div>
  );
}

const bottomNavStyle = {
  position: 'fixed',
  bottom: 0,
  left: 0,
  right: 0,
  background: '#FFF',
  borderTop: '1px solid #EAE5D9',
  display: 'flex',
  justifyContent: 'space-around',
  alignItems: 'center',
  padding: '10px 0',
  zIndex: 1000,
  boxShadow: '0 -2px 10px rgba(0,0,0,0.03)'
};

const navItemStyle = {
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  cursor: 'pointer',
  gap: '3px'
};

const fabStyle = {
  position: 'absolute',
  right: '20px',
  top: '-25px',
  background: '#C28E38',
  color: '#FFF',
  width: '50px',
  height: '50px',
  borderRadius: '50%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: '28px',
  boxShadow: '0 4px 10px rgba(0,0,0,0.2)',
  cursor: 'pointer',
  fontWeight: 'bold'
};
